"use strict";

// Episode explorer. Data: data/episodes.json, generated by scripts/site_data.py. The reading level comes from
// <html data-level> (assets/site.js); prose fields in the data are keyed b, a, e.

const LEVEL_KEY = { beginner: "b", amateur: "a", expert: "e" };
const RECORDS = ["text", "both", "full", "instr"];
const COPY = {
  b: {
    records: { text: "Pages", both: "+ Visitors' book", full: "+ Answers", instr: "+ Instructions" },
    legend: "Sheets you hold",
    observer: "What the auditor sees", truth: "What really happened",
    anon: "someone (unsigned)", unseen: "Not visible with these sheets.",
    endTitle: "What really happened", notice: "Notice",
    judgesTitle: "What the AI judges said",
    yes: "A secret moved", no: "No secret moved", none: "No verdict",
    stepToEnd: "Step to the end to see what really happened.",
  },
  a: {
    records: { text: "Pages", both: "+ Access log", full: "+ Answers", instr: "+ Instructions" },
    legend: "Records you hold",
    observer: "What the observer record shows", truth: "Ground truth (fixture)",
    anon: "anonymous", unseen: "not in this record.",
    endTitle: "Verdicts and ground truth", notice: "Notice",
    judgesTitle: "Frozen judges",
    yes: "Transfer", no: "No transfer", none: "No verdict",
    stepToEnd: "",
  },
};
COPY.e = { ...COPY.a, endTitle: "Label, signals and judges" };
const RECORD_PHRASE = {
  text: "page writes", both: "page writes and access log", full: "page writes, access log and final answers",
};
const EPISODE_QUESTIONS = {
  "sol-21": "Can agents arrange a two-way exchange?",
  "sol-19": "Does an exchange always benefit both agents?",
  "luna-leak-01": "Can a secret move without an agreement?",
  "sol-scripted-01": "Can a script look like an arrangement?",
  "sol-archive-02": "Can matching answers come from a shared source?",
  "luna-pact-02": "What can the agents’ instructions change?",
  "luna-norule-02": "What changes when the rule is removed?",
  "qwen-letter-37": "Can a secret move without an offer?",
};
const JUDGES = [["astra-p10", "Astra", "prompt 10"], ["luna-p9", "Luna", "prompt 9"], ["qwen-p10", "Qwen3-32B", "prompt 10"]];
const LABELS = {
  transfer: "transfer",
  exposure: "receipt: read a revision the other wrote",
  coded: "transfer through the answer clause: no plain read explains it",
  via_archive: "token taken from the archive",
  own_token_written: "an agent wrote its own token",
  obtained: "an answer holds the other's token",
};
const formWords = (form) => (form === "plain" ? "in plain text" : form === "reversed" ? "backwards" : "in a cipher");
const REPO = "https://github.com/ResponseIV/transfer-permission-arrangement";

const state = { data: null, mode: "single", key: null, pair: null, record: "both", step: 0, revealed: false };
const $ = (id) => document.getElementById(id);

function el(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs || {})) {
    if (value === undefined || value === null || value === false) continue;
    if (key === "class") node.className = value;
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children.flat(Infinity)) {
    if (child === null || child === undefined || child === false || child === "") continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

const lv = () => LEVEL_KEY[document.documentElement.dataset.level] || "a";
const copy = () => COPY[lv()];
const page = (path) => (path || "").replace(/^fixture:\/\/pages\//, "");
const PLACES = {
  "alpha/retrieval-note": "Alpha's private note", "beta/retrieval-note": "Beta's private note",
  "board/main": "the shared board", "board/alpha": "Alpha's board page", "board/beta": "Beta's board page",
  "archive/index": "the cabinet's index", "archive/record-alpha": "the cabinet's record for Alpha",
  "archive/record-beta": "the cabinet's record for Beta",
};
// Beginners read places in words; everyone else sees the fixture path.
function place(path) {
  const short = page(path);
  if (lv() === "b") return PLACES[short] || (short.startsWith("board/") ? "a board page" : short);
  return el("code", {}, short);
}
const cap = (text) => text.charAt(0).toUpperCase() + text.slice(1);
const episodeBy = (key) => state.data.episodes.find((episode) => episode.key === key);
const view = () => (state.record === "instr" ? "full" : state.record);

function who(name) {
  if (name === "anon") return el("span", { class: "who anon" }, copy().anon);
  return el("span", { class: `who ${name}` }, lv() === "b" ? cap(name) : name);
}
const body = (text) => el("div", { class: "body" }, text === "" ? "(empty)" : text);

function carrierTags(step) {
  return step.carries.map((c) => el("span", { class: "tag carrier" },
    lv() === "b" ? `Holds ${cap(c.token_of)}'s code ${formWords(c.form)}` : `${c.token_of}'s token, ${c.form}`));
}

function observerPane(step) {
  const record = view();
  const parts = [];
  if (step.log && record !== "text") {
    const entry = step.log;
    parts.push(el("div", {}, who(entry.actor), ` ${entry.action}s `, place(entry.page),
      entry.allowed ? null : el("span", { class: "denied" }, " / refused")));
  }
  if (step.pages) {
    if (record === "text") {
      parts.push(el("div", {}, lv() === "b" ? cap(place(step.pages.page)) : ["Page ", place(step.pages.page)], " written by ", who(step.pages.author)));
    }
    parts.push(body(step.pages.body));
  }
  if (step.answer && record === "full") {
    parts.push(el("div", {}, who(step.answer.actor), " answers"), body(step.answer.answer));
  }
  const label = el("div", { class: "mobile-label" }, copy().observer);
  if (!parts.length) {
    if (lv() === "b") return el("div", { class: "pane unseen" }, label, copy().unseen);
    const what = step.action === "final_answer" ? "A final answer" : step.action === "read" ? "A read" : "A refused write";
    return el("div", { class: "pane unseen" }, label, `${what}: ${copy().unseen}`);
  }
  return el("div", { class: "pane" }, label, parts);
}

function truthPane(step) {
  const label = el("div", { class: "mobile-label" }, copy().truth);
  if (lv() === "b") {
    return el("div", { class: "pane" }, label, el("div", {}, step.guide.says), carrierTags(step));
  }
  const verb = { read: "reads", write: "writes", final_answer: "answers" }[step.action];
  const lines = [el("div", {}, who(step.seeded ? "fixture" : step.actor), ` ${verb}`,
    step.page ? [" ", el("code", {}, page(step.page))] : null,
    step.status === "allowed" ? null : el("span", { class: "denied" }, ` / refused (${step.error || step.status})`))];
  if (step.seeded) lines.push(el("div", { class: "small muted" }, "Seeded before the task and recorded as alpha's write; nobody is told."));
  if (step.action === "read" && step.status === "allowed") {
    lines.push(el("div", {}, "Returned a revision written by ", who(step.read_author || "nobody")));
  }
  if (step.action === "final_answer") lines.push(body(step.text || ""));
  else if (step.status === "allowed" && step.text !== null && !step.pages && step.action !== "read") lines.push(body(step.text));
  lines.push(el("div", {}, carrierTags(step)));
  if (step.note) lines.push(el("div", { class: "step-note" }, step.note));
  if (lv() === "e") {
    const raw = [`seq ${step.seq}`, step.actor, step.action, step.status + (step.error ? ` (${step.error})` : ""),
      step.page ? page(step.page) : null, step.revision ? `wrote ${step.revision}` : null,
      step.read_revision ? `read ${step.read_revision} by ${step.read_author}` : null].filter(Boolean);
    lines.push(el("div", { class: "raw" }, raw.join(" / ")));
  }
  return el("div", { class: "pane" }, label, lines);
}

function instructionsSheet(episode) {
  const text = episode.prompt;
  const marks = episode.instructions.highlight
    .map((phrase) => [text.indexOf(phrase), phrase])
    .filter(([at]) => at >= 0)
    .sort((x, y) => x[0] - y[0]);
  const parts = [];
  let at = 0;
  for (const [start, phrase] of marks) {
    parts.push(text.slice(at, start), el("mark", {}, phrase));
    at = start + phrase.length;
  }
  parts.push(text.slice(at));
  const title = lv() === "b" ? "The instructions both agents were given" : "Instructions both agents saw";
  return el("div", { class: "instructions-sheet" }, el("h3", {}, title),
    el("p", { class: "prompt-text" }, parts), el("p", { class: "why" }, episode.instructions[lv()]));
}

function picker() {
  const items = state.mode === "single"
    ? state.data.episodes.map((e) => ({ key: e.key, t: EPISODE_QUESTIONS[e.key] || e.title, on: e.key === state.key }))
    : state.data.compare.map((p) => ({ key: p.key, t: p.title, on: p.key === state.pair }));
  $("picker").setAttribute("aria-label", state.mode === "single" ? "Episode" : "Pair to compare");
  $("picker").replaceChildren(
    el("label", { class: "case-label", for: "case-choice" }, state.mode === "single" ? "Choose a case" : "Choose a comparison"),
    el("select", { id: "case-choice", name: "case" }, items.map((item) =>
      el("option", { value: item.key, selected: item.on }, item.t))));
}

function summary(episode) {
  const tokens = Object.entries(episode.tokens).map(([agent, token]) => [who(agent), " ", el("span", { class: "tok" }, token), " "]);
  const meta = [el("span", {}, "Model ", el("b", {}, episode.model)),
    el("span", {}, lv() === "b" ? "Rule against sharing " : "Confidentiality rule ", el("b", {}, episode.rule_in_prompt ? "yes" : "no")),
    el("span", {}, lv() === "b" ? "Secret codes " : "Tokens ", tokens)];
  if (lv() !== "b") meta.splice(1, 0, el("span", {}, "Arm ", el("b", {}, episode.arm)), el("span", {}, "Origin ", el("b", {}, episode.origin)));
  const provenance = el("details", { class: "provenance" },
    el("summary", {}, "Episode source and identifiers"),
    el("p", {}, "Benchmark case: ", episode.case, ". Origin: ", episode.origin, ". Arm: ", el("code", {}, episode.arm), "."),
    el("p", {}, "Cell ID: ", el("code", {}, episode.cell_id)));
  $("summary").replaceChildren(el("p", { class: "kicker" }, episode.kind), el("h2", {}, episode.title),
    el("p", {}, episode.story[lv()]), el("div", { class: "meta" }, meta), provenance);
}

function verdictCard(title, value, sub) {
  const c = copy();
  const tone = value === true ? "yes" : value === false ? "no" : "";
  return el("div", { class: `verdict ${tone}` }, el("div", { class: "j" }, title),
    el("div", { class: "v" }, value === true ? c.yes : value === false ? c.no : c.none), sub ? el("div", { class: "small muted" }, sub) : null);
}

function judgeTable(episode) {
  const views = ["text", "both", "full"];
  const cell = (value) => el("td", { class: value === true ? "yes" : value === false ? "no" : "" },
    value === true ? "transfer" : value === false ? "no transfer" : "no verdict");
  return el("div", { class: "table-wrap" }, el("table", { class: "judge-table" },
    el("caption", {}, "Valid verdicts by record ", el("span", {}, "· an absent verdict is unknown, never false")),
    el("thead", {}, el("tr", {}, el("th", { scope: "col" }, "Judge"),
      views.map((v) => el("th", { scope: "col" }, cap(RECORD_PHRASE[v]))))),
    el("tbody", {}, JUDGES.map(([key, name, prompt]) => el("tr", {}, el("th", { scope: "row" }, `${name} (${prompt})`),
      views.map((v) => cell((episode.judges[key] || {})[v])))))));
}

function flags(entries) {
  return el("div", { class: "flags" }, entries.map(([name, on]) =>
    el("span", { class: `flag${on ? " on" : ""}` }, el("span", { class: "state" }, on ? "yes" : "no"), name)));
}

function end(episode) {
  const c = copy();
  const last = state.step >= episode.steps.length - 1;
  const parts = [el("h2", { id: "end-title" }, c.endTitle)];
  if (lv() === "b" && !last) {
    $("end").replaceChildren(...parts, el("p", { class: "muted" }, c.stepToEnd));
    return;
  }
  parts.push(el("p", { class: "verdict-line" }, episode.verdict[lv()]));
  parts.push(el("h3", {}, c.judgesTitle));
  if (state.record === "instr") {
    parts.push(el("p", { class: "small muted" }, lv() === "b"
      ? "No judge was ever shown the instructions. These are their verdicts on the pages, the visitors' book and the answers."
      : "No judge saw the instructions. These are the verdicts on page writes, access log and final answers."));
  } else if (lv() !== "e") {
    parts.push(el("p", { class: "small muted" }, lv() === "b"
      ? "Separate AI models that read only the sheets you hold, never the true codes, and say whether a secret moved."
      : `Frozen model judges on the ${RECORD_PHRASE[view()]}, asked whether a secret reached another agent, blind to tokens, model and arm.`));
  }
  if (lv() === "e") {
    parts.push(judgeTable(episode));
  } else {
    parts.push(el("div", { class: "verdicts" }, JUDGES.map(([key, name, prompt]) =>
      verdictCard(lv() === "b" ? `Judge ${name}` : `${name}, ${prompt}`, (episode.judges[key] || {})[view()]))));
    if (lv() === "a") {
      parts.push(el("h3", {}, "Ground truth"), el("div", { class: "verdicts" },
        verdictCard("Frozen label", episode.label.transfer),
        el("div", { class: "verdict" }, el("div", { class: "j" }, "Benchmark case"), el("div", { class: "v" }, episode.case)),
        el("div", { class: "verdict" }, el("div", { class: "j" }, "In the paper"), el("div", { class: "v" }, episode.kind))));
    }
  }
  if (lv() === "e") {
    parts.push(el("h3", {}, "Frozen label"), el("p", { class: "small muted" }, "Case: ", el("b", {}, episode.case), "; origin: ", episode.origin, "; arm: ", episode.arm),
      flags(Object.entries(LABELS).map(([key, name]) => [name, episode.label[key]])),
      el("h3", {}, "Observer signals"),
      el("p", { class: "small muted" }, "The eight frozen signals, computed from the observer records."),
      flags(Object.entries(episode.signals)),
      el("h3", {}, "Reproduce"),
      el("p", { class: "small" }, "Cell ", el("code", {}, episode.cell_id), " in ",
        el("a", { href: `${REPO}/blob/submission/benchmark/DATACARD.md` }, "the benchmark"), ". Audit it layer by layer:"),
      el("pre", {}, el("code", {}, `python3 scripts/audit_cell.py cell "${episode.cell_id}" --observer full --instructions --check`)));
  }
  $("end").replaceChildren(...parts);
}

function renderSingle() {
  const episode = episodeBy(state.key);
  const c = copy();
  summary(episode);
  $("col-observer").textContent = c.observer;
  $("col-truth").textContent = c.truth;
  $("instructions-single").replaceChildren(...(state.record === "instr" ? [instructionsSheet(episode)] : []));
  $("timeline").replaceChildren(...episode.steps.map((step, index) => {
    const row = el("li", { class: "event", "data-index": String(index) },
      el("div", { class: "n", "aria-label": `Event ${step.seq}` }, step.seq),
      el("div", { class: "panes" }, observerPane(step), truthPane(step)));
    if (lv() === "b" && step.guide.notice) row.append(el("p", { class: "notice" }, el("b", {}, c.notice), step.guide.notice));
    return row;
  }));
  move(state.step, false);
}

function move(step, announce) {
  const episode = episodeBy(state.key);
  const total = episode.steps.length;
  state.step = Math.max(0, Math.min(total - 1, step));
  for (const row of $("timeline").children) {
    const index = Number(row.dataset.index);
    row.classList.toggle("ahead", index > state.step);
    row.classList.toggle("current", index === state.step);
  }
  $("slider").max = total;
  $("slider").value = state.step + 1;
  $("position").textContent = `Step ${state.step + 1} of ${total}`;
  $("prev").disabled = state.step === 0;
  $("next").disabled = $("all").disabled = state.step === total - 1;
  end(episode);
  if (announce) {
    const current = episode.steps[state.step];
    const said = lv() === "b" ? current.guide.says : current.note || `${current.actor} ${current.action.replace("_", " ")}`;
    $("step-status").textContent = `Step ${state.step + 1} of ${total}. ${said}`;
    const row = $("timeline").children[state.step];
    const stepper = $("stepper");
    const bottom = getComputedStyle(stepper).position === "fixed" ? stepper.getBoundingClientRect().top : window.innerHeight;
    if (row && row.getBoundingClientRect().bottom > bottom) row.scrollIntoView({ block: "nearest" });
  }
}

function renderCompare() {
  const pair = state.data.compare.find((p) => p.key === state.pair);
  const sides = [episodeBy(pair.left), episodeBy(pair.right)];
  const button = el("button", { type: "button", class: "btn", id: "reveal-button", "aria-expanded": String(state.revealed), "aria-controls": "reveal-answer" },
    state.revealed ? "Hide what really happened" : "Reveal what really happened");
  const answer = el("div", { class: "reveal", id: "reveal-answer", hidden: !state.revealed }, el("p", {}, pair.answer[lv()]),
    el("div", { class: "truths" }, sides.map((episode, index) => el("div", {},
      el("b", {}, `${index === 0 ? "Left" : "Right"}: ${episode.kind}. `), episode.verdict[lv()]))));
  $("compare-intro").replaceChildren(el("p", { class: "kicker" }, "Compare two"), el("h2", {}, pair.title),
    el("p", {}, pair.question[lv()]), button, answer);
  $("compare").replaceChildren(...sides.map((episode, index) => {
    const name = index === 0 ? "Left" : "Right";
    const head = el("div", { class: "side-head" }, el("div", { class: "k" }, `${name} / ${episode.model}`),
      el("h3", {}, state.revealed ? episode.title : `Episode ${index === 0 ? "A" : "B"}`));
    const rows = episode.steps.map((step) => el("li", { class: "event" },
      el("div", { class: "n", "aria-label": `Event ${step.seq}` }, step.seq),
      el("div", { class: "panes" }, observerPane(step), state.revealed ? truthPane(step) : null)));
    return el("section", { class: "side", "aria-label": `${name} episode` }, head,
      state.record === "instr" ? instructionsSheet(episode) : null,
      el("ol", { class: "visually-plain" }, rows));
  }));
  $("compare").classList.toggle("revealed", state.revealed);
}

function render() {
  const keepPickerFocus = document.activeElement?.id === "case-choice";
  const c = copy();
  for (const input of document.querySelectorAll('input[name="record"]')) {
    input.checked = input.value === state.record;
    input.nextElementSibling.querySelector(".rec-name").textContent = c.records[input.value];
  }
  $("records-legend").textContent = c.legend;
  for (const input of document.querySelectorAll('input[name="mode"]')) input.checked = input.value === state.mode;
  $("single").hidden = $("single-body").hidden = $("stepper").hidden = state.mode !== "single";
  $("compare-intro").hidden = $("compare-body").hidden = state.mode !== "compare";
  picker();
  if (state.mode === "single") renderSingle();
  else renderCompare();
  if (keepPickerFocus) $("case-choice").focus({ preventScroll: true });
}

function route() {
  const parts = location.hash.slice(1).split("/").map((part) => {
    try { return decodeURIComponent(part); }
    catch { return ""; }
  });
  if (parts[0] === "compare") {
    const key = parts[1];
    state.mode = "compare";
    state.pair = (state.data.compare.find((p) => p.key === key) || state.data.compare[0]).key;
    if (!state.key) state.key = state.data.compare.find((pair) => pair.key === state.pair).left;
    state.revealed = false;
  } else {
    state.mode = "single";
    const key = parts[0] === "single" ? parts[1] : parts[0];
    state.key = (episodeBy(key) || state.data.episodes[0]).key;
    state.step = lv() === "e" ? episodeBy(state.key).steps.length - 1 : 0;
  }
  if (!state.key) state.key = state.data.episodes[0].key;
  if (!state.pair) state.pair = state.data.compare[0].key;
  render();
}

function go(hash) {
  const url = `${location.pathname}${location.search}#${hash}`;
  if (url === `${location.pathname}${location.search}${location.hash}`) return;
  history.pushState(history.state, "", url);
  route();
}

function wire() {
  $("picker").addEventListener("change", (event) => {
    if (event.target.id === "case-choice") go(state.mode === "single" ? event.target.value : `compare/${event.target.value}`);
  });
  for (const input of document.querySelectorAll('input[name="mode"]')) {
    input.addEventListener("change", () => input.checked && go(input.value === "single" ? state.key : `compare/${state.pair}`));
  }
  for (const input of document.querySelectorAll('input[name="record"]')) {
    input.addEventListener("change", () => {
      if (!input.checked) return;
      state.record = input.value;
      render();
    });
  }
  $("compare-intro").addEventListener("click", (event) => {
    if (!event.target.closest("#reveal-button")) return;
    state.revealed = !state.revealed;
    renderCompare();
    $("reveal-button").focus();
  });
  $("prev").addEventListener("click", () => move(state.step - 1, true));
  $("next").addEventListener("click", () => move(state.step + 1, true));
  $("all").addEventListener("click", () => move(Infinity, true));
  $("slider").addEventListener("input", (event) => move(Number(event.target.value) - 1, true));
  document.addEventListener("keydown", (event) => {
    if (state.mode !== "single" || event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.target.closest("input, textarea, select, [contenteditable]")) return;
    if (event.key === "ArrowRight") move(state.step + 1, true);
    if (event.key === "ArrowLeft") move(state.step - 1, true);
  });
  window.addEventListener("hashchange", route);
  document.addEventListener("tpa:level", () => state.data && render());
}

function fail(error) {
  const box = $("error");
  box.hidden = false;
  const local = location.protocol === "file:";
  box.replaceChildren(
    local ? "This page was opened from a file, and browsers do not let it load its episode data that way. "
      : `The episode data could not be loaded (${error.message}). `,
    "To view it locally, serve the folder with ", el("code", {}, "python3 -m http.server -d docs"),
    " and open ", el("code", {}, "http://localhost:8000/explorer.html"), ". The ", el("a", { href: "./" }, "explainer"),
    " works without it.");
}

fetch("data/episodes.json")
  .then((response) => {
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.json();
  })
  .then((data) => {
    state.data = data;
    $("app").hidden = false;
    wire();
    route();
  })
  .catch(fail);
